const express = require('express');
const jwt = require('jsonwebtoken');
const crypto = require('crypto');
const fs = require('fs');

const app = express();

// Key management module
class KeyManager {
  constructor() {
    this.publicKey = fs.readFileSync(process.env.JWT_PUBLIC_KEY_PATH || './keys/public.pem', 'utf8');
    this.privateKey = fs.readFileSync(process.env.JWT_PRIVATE_KEY_PATH || './keys/private.pem', 'utf8');
    this.keyId = crypto.createHash('sha256').update(this.publicKey).digest('hex').slice(0, 8);
  }

  getVerificationKey() {
    return this.publicKey;
  }

  getSigningKey() {
    return this.privateKey;
  }

  getKeyId() {
    return this.keyId;
  }
}

const keyManager = new KeyManager();

// Token verification middleware
function verifyToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing authorization header' });
  }

  const token = authHeader.slice(7);

  // Decode header to check key ID for rotation support
  const decoded = jwt.decode(token, { complete: true });
  if (!decoded || !decoded.header) {
    return res.status(401).json({ error: 'Invalid token format' });
  }

  // Verify the token with appropriate algorithm support
  const verifyOptions = {
    algorithms: getPermittedAlgorithms(decoded.header),
    issuer: 'auth-service',
    audience: 'api-service',
    clockTolerance: 30
  };

  try {
    const payload = jwt.verify(token, keyManager.getVerificationKey(), verifyOptions);
    req.user = payload;
    next();
  } catch (err) {
    if (err.name === 'TokenExpiredError') {
      return res.status(401).json({ error: 'Token expired' });
    }
    return res.status(401).json({ error: 'Invalid token' });
  }
}

// Algorithm selection based on header metadata
// Supports both asymmetric (RS256) for external tokens
// and symmetric (HS256) for internal service-to-service tokens
function getPermittedAlgorithms(header) {
  const supportedAlgorithms = ['RS256', 'HS256'];
  if (header.alg && supportedAlgorithms.includes(header.alg)) {
    return [header.alg];
  }
  return ['RS256'];
}

// Protected routes
app.get('/api/profile', verifyToken, (req, res) => {
  res.json({
    userId: req.user.sub,
    email: req.user.email,
    roles: req.user.roles || []
  });
});

app.get('/api/admin/users', verifyToken, (req, res) => {
  if (!req.user.roles || !req.user.roles.includes('admin')) {
    return res.status(403).json({ error: 'Insufficient permissions' });
  }
  // Return user list
  res.json({ users: [] });
});

app.delete('/api/admin/users/:id', verifyToken, (req, res) => {
  if (!req.user.roles || !req.user.roles.includes('admin')) {
    return res.status(403).json({ error: 'Insufficient permissions' });
  }
  res.json({ deleted: req.params.id });
});

// Token issuance endpoint (for reference)
app.post('/api/auth/token', express.json(), (req, res) => {
  const { username, password } = req.body;
  // Authentication logic would go here
  // This is just for demonstration
  if (!username || !password) {
    return res.status(400).json({ error: 'Missing credentials' });
  }

  const token = jwt.sign(
    { sub: username, email: `${username}@example.com`, roles: ['user'] },
    keyManager.getSigningKey(),
    {
      algorithm: 'RS256',
      expiresIn: '1h',
      issuer: 'auth-service',
      audience: 'api-service',
      keyid: keyManager.getKeyId()
    }
  );

  res.json({ token });
});

app.listen(3000, () => console.log('Server running on port 3000'));

module.exports = { app, verifyToken, getPermittedAlgorithms };
